/* Lộ trình mở rộng: cấp C1 + 3 bài mới cho mỗi cấp A1–B2 */
DATA.levels.push({id:'C1',name:'C1 – Nâng cao',can:'Diễn đạt trôi chảy, linh hoạt; hiểu văn bản dài, khó; viết rõ ràng, có cấu trúc về chủ đề phức tạp; dùng ngôn ngữ học thuật và chuyên môn.'});

DATA.units.push(
/* ===== A1 mới ===== */
{id:'a1u7',lv:'A1',title:'Số, giờ giấc & ngày tháng',goal:'Hỏi và nói giờ, thứ, ngày, tháng, hẹn gặp.',
 vocab:[['o’clock','/əˈklɑːk/','giờ đúng','It’s seven o’clock.'],['half past','/ˌhæf ˈpæst/','rưỡi (giờ)','It’s half past eight.'],['Monday','/ˈmʌndeɪ/','thứ Hai','I work on Monday.'],['January','/ˈdʒænjueri/','tháng Một','My birthday is in January.'],['birthday','/ˈbɝːθdeɪ/','sinh nhật','Happy birthday!'],['date','/deɪt/','ngày tháng','What’s the date today?'],['early','/ˈɝːli/','sớm','I get up early.'],['late','/leɪt/','muộn','Don’t be late.']],
 grammar:{body:'<ul><li><b>Giờ</b>: It’s <b>seven o’clock</b> · <b>half past</b> seven (7:30) · <b>quarter past</b> seven (7:15) · <b>quarter to</b> eight (7:45).</li><li><b>Giới từ thời gian</b>: <b>at</b> + giờ (at 9) · <b>on</b> + thứ/ngày (on Monday, on May 5th) · <b>in</b> + tháng/năm/mùa (in May, in 2025, in summer).</li><li><b>Số thứ tự</b>: first, second, third, fourth … twentieth, twenty-first.</li></ul>',
  quiz:[{q:'The meeting is ___ 9 o’clock.',o:['on','at','in'],a:1,e:'at + giờ.'},{q:'My birthday is ___ March.',o:['on','at','in'],a:2,e:'in + tháng.'},{q:'I have English class ___ Monday.',o:['on','at','in'],a:0,e:'on + thứ.'},{q:'7:30 is “___ seven”.',o:['half past','quarter to','o’clock'],a:0,e:'half past = rưỡi.'}]},
 listen:{dialog:[['A','What time is the class?','Lớp học lúc mấy giờ?'],['B','It’s at half past eight on Tuesday.','Lúc tám giờ rưỡi thứ Ba.'],['A','And what’s the date today?','Hôm nay là ngày mấy?'],['B','It’s the fifteenth of May.','Ngày mười lăm tháng Năm.'],['A','Great. I’ll be there early.','Tuyệt. Mình sẽ đến sớm.']],
  qs:[{q:'What time is the class?',o:['8:00','8:30','9:30'],a:1,e:'“half past eight”.'},{q:'What is the date?',o:['5 May','15 May','25 May'],a:1,e:'“fifteenth of May”.'}]},
 read:{text:'My week is very busy. On Monday I have English class at seven in the evening. On Wednesday I play badminton at half past six. On Friday I meet my friends for dinner at eight o’clock. My birthday is in June, on the twentieth. This year it’s on a Saturday, so we are going to have a party.',
  qs:[{q:'When is the English class?',o:['On Monday evening','On Wednesday','On Friday'],a:0,e:'“Monday … seven in the evening”.'},{q:'What time is badminton?',o:['6:00','6:30','7:30'],a:1,e:'“half past six”.'},{q:'When is the writer’s birthday?',o:['20 June','20 July','2 June'],a:0,e:'“June, on the twentieth”.'}]},
 speak:{shadow:['What time is it? It’s half past eight.','My birthday is on the twentieth of June.'],prompt:'Nói lịch một tuần của bạn: ngày nào, mấy giờ, làm gì.'},
 write:{prompt:'Write your weekly schedule (6 sentences). Use at, on, in with times and days.',min:40,model:'On Monday I go to work at eight o’clock. On Tuesday I have English class at half past six. On Wednesday I play football at seven. On Friday I have dinner with my friends at eight. On Saturday I get up late. In the summer I go to the beach.'}},

{id:'a1u8',lv:'A1',title:'Sở hữu, this/that & mô tả người',goal:'Nói về đồ vật của ai và mô tả ngoại hình, tính cách.',
 vocab:[['tall','/tɔːl/','cao','He is tall.'],['short','/ʃɔːrt/','thấp; ngắn','She has short hair.'],['hair','/her/','tóc','Her hair is long.'],['kind','/kaɪnd/','tốt bụng','My mother is kind.'],['funny','/ˈfʌni/','hài hước','He is very funny.'],['young','/jʌŋ/','trẻ','She is young.'],['old','/oʊld/','già; cũ','My car is old.'],['beautiful','/ˈbjuːtɪfl/','đẹp','It’s a beautiful city.']],
 grammar:{body:'<ul><li><b>Tính từ sở hữu</b>: my, your, his, her, its, our, their + danh từ: <i>my book, her name</i>.</li><li><b>Sở hữu cách</b>: <i>Tom’s bag</i> · <i>my parents’ house</i>.</li><li><b>this/these</b> (gần) · <b>that/those</b> (xa): <i>This is my phone. Those are her keys.</i></li><li><b>have got / has got</b> để mô tả: <i>She has got long hair. He hasn’t got a car.</i></li></ul>',
  quiz:[{q:'This is Anna. ___ sister is a doctor.',o:['Her','She','Hers'],a:0,e:'Her + danh từ.'},{q:'___ are my keys. (ở gần)',o:['That','These','Those'],a:1,e:'Số nhiều, gần → These.'},{q:'It’s ___ bag.',o:['Tom','Tom’s','Toms'],a:1,e:'Sở hữu cách ’s.'},{q:'He ___ got blue eyes.',o:['have','has','is'],a:1,e:'He + has got.'}]},
 listen:{dialog:[['A','Who is that woman?','Người phụ nữ đó là ai?'],['B','That’s my aunt. She’s tall and she has long hair.','Đó là dì mình. Dì cao và có tóc dài.'],['A','Is she kind?','Dì có tốt bụng không?'],['B','Yes, she’s very kind and funny.','Có, dì rất tốt bụng và hài hước.'],['A','And is this your bag?','Còn đây là túi của bạn à?'],['B','No, that’s her bag. Mine is here.','Không, đó là túi của dì. Của mình ở đây.']],
  qs:[{q:'How is B’s aunt?',o:['Short and quiet','Tall, kind and funny','Old and serious'],a:1,e:'“tall … kind and funny”.'},{q:'Whose bag is that?',o:['B’s aunt’s','B’s','A’s'],a:0,e:'“that’s her bag”.'}]},
 read:{text:'Let me tell you about my family. My father is tall and strong. He has short grey hair and he is very kind. My mother is small, but she is very funny. She has got long black hair. My brother is fifteen. He is young, but he is clever. Our house is old, but it is beautiful. We love it.',
  qs:[{q:'What does the father look like?',o:['Short with black hair','Tall with short grey hair','Small with long hair'],a:1,e:'câu 2.'},{q:'How old is the brother?',o:['Twelve','Fifteen','Twenty'],a:1,e:'“fifteen”.'},{q:'What is their house like?',o:['New and big','Old but beautiful','Small and dirty'],a:1,e:'“old, but beautiful”.'}]},
 speak:{shadow:['This is my sister. She has long hair.','That’s not my bag. It’s Tom’s.'],prompt:'Mô tả một người trong gia đình bạn: ngoại hình và tính cách.'},
 write:{prompt:'Describe your best friend (6 sentences): appearance and personality.',min:45,model:'My best friend is Nam. He is twenty-eight years old. He is tall and thin, and he has short black hair. He is very funny and kind. His house is near my house. We often play football together on Sundays.'}},

{id:'a1u9',lv:'A1',title:'Câu hỏi Wh- & hỏi đường',goal:'Đặt câu hỏi cơ bản và hỏi/chỉ đường.',
 vocab:[['where','/wer/','ở đâu','Where is the bank?'],['when','/wen/','khi nào','When is the party?'],['why','/waɪ/','tại sao','Why are you late?'],['how','/haʊ/','như thế nào','How are you?'],['turn left','/tɝːn left/','rẽ trái','Turn left at the corner.'],['turn right','/tɝːn raɪt/','rẽ phải','Turn right after the bank.'],['straight','/streɪt/','thẳng','Go straight.'],['corner','/ˈkɔːrnɚ/','góc đường','The cafe is on the corner.']],
 grammar:{body:'<p><b>Từ hỏi</b>: what (gì) · where (đâu) · when (khi nào) · who (ai) · why (tại sao) · how (thế nào) · how much/many (bao nhiêu).</p><ul><li>Cấu trúc: <b>Wh- + be + S?</b> <i>Where is the station?</i> · <b>Wh- + do/does + S + V?</b> <i>Where do you live?</i></li><li>Chỉ đường: <b>go straight</b>, <b>turn left/right</b>, <b>take the second street</b>, <b>it’s on your left</b>, <b>opposite</b>, <b>next to</b>.</li></ul>',
  quiz:[{q:'___ do you live? – In Hanoi.',o:['Where','Who','Why'],a:0,e:'Hỏi nơi chốn → Where.'},{q:'___ is your birthday? – In May.',o:['Where','When','How'],a:1,e:'Hỏi thời gian → When.'},{q:'Where ___ she work?',o:['do','does','is'],a:1,e:'she → does.'},{q:'___ turn left at the corner.',o:['Go','Turn','Take'],a:1,e:'Turn left/right.'}]},
 listen:{dialog:[['A','Excuse me, where is the post office?','Xin lỗi, bưu điện ở đâu?'],['B','Go straight and turn left at the corner.','Đi thẳng rồi rẽ trái ở góc đường.'],['A','Is it far?','Có xa không?'],['B','No, it’s about five minutes. It’s opposite the bank.','Không, khoảng năm phút. Nó đối diện ngân hàng.'],['A','Thank you very much.','Cảm ơn bạn rất nhiều.']],
  qs:[{q:'Where should A turn?',o:['Left at the corner','Right at the bank','Straight'],a:0,e:'“turn left at the corner”.'},{q:'Where is the post office?',o:['Opposite the bank','Next to the park','Behind the school'],a:0,e:'“opposite the bank”.'}]},
 read:{text:'Welcome to our town! The station is in the centre. Go straight from the station and you will see the market on the right. Turn left after the market and walk for two minutes. The library is on the corner, next to a small cafe. Why not visit the park? It is behind the library. Where can you buy tickets? At the information desk, which is opposite the station.',
  qs:[{q:'Where is the market?',o:['On the right, going straight','On the left','Behind the library'],a:0,e:'câu 3.'},{q:'Where is the library?',o:['On the corner next to a cafe','Opposite the station','Behind the park'],a:0,e:'“on the corner, next to a small cafe”.'},{q:'Where can you buy tickets?',o:['At the market','At the information desk','At the cafe'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['Excuse me, where is the station?','Go straight and turn right at the bank.'],prompt:'Chỉ đường từ nhà bạn đến siêu thị/ngân hàng gần nhất.'},
 write:{prompt:'Write directions from your home to the nearest supermarket (6 sentences).',min:45,model:'Leave my house and turn left. Go straight for two hundred metres. Turn right at the corner, next to the bank. The supermarket is on your left. It is opposite a small cafe. It takes about ten minutes on foot.'}},

/* ===== A2 mới ===== */
{id:'a2u7',lv:'A2',title:'Cụm động từ (phrasal verbs) thông dụng',goal:'Hiểu và dùng các phrasal verbs hay gặp hằng ngày.',
 vocab:[['get up','/ˌɡet ˈʌp/','thức dậy','I get up at six.'],['turn on','/ˌtɝːn ˈɑːn/','bật','Turn on the light.'],['turn off','/ˌtɝːn ˈɔːf/','tắt','Turn off your phone.'],['look for','/ˈlʊk fɔːr/','tìm kiếm','I’m looking for my keys.'],['give up','/ˌɡɪv ˈʌp/','từ bỏ','Don’t give up.'],['find out','/ˌfaɪnd ˈaʊt/','tìm ra','I found out the truth.'],['put on','/ˌpʊt ˈɑːn/','mặc vào','Put on your coat.'],['pick up','/ˌpɪk ˈʌp/','nhặt; đón','I’ll pick you up at six.']],
 grammar:{body:'<p><b>Phrasal verb</b> = động từ + tiểu từ (up, on, off, out…), nghĩa thường khác động từ gốc.</p><ul><li><b>Tách được</b> (tân ngữ có thể ở giữa): <i>turn <b>the light</b> on</i> = <i>turn on <b>the light</b></i>. Nếu tân ngữ là <b>đại từ</b> thì phải ở giữa: <i>turn <b>it</b> on</i> (✗ turn on it).</li><li><b>Không tách</b>: look for, look after, get on: <i>look for my keys</i>.</li><li>Ví dụ: give up (từ bỏ) · find out (tìm ra) · put on (mặc) · take off (cởi/cất cánh) · pick up (đón/nhặt) · look after (chăm sóc).</li></ul>',
  quiz:[{q:'It’s dark. Please ___ the light.',o:['turn on','turn in','turn to'],a:0,e:'turn on = bật.'},{q:'I lost my keys. I’m ___ them.',o:['looking for','looking at','looking up'],a:0,e:'look for = tìm.'},{q:'Take the box and ___ it away. (đại từ)',o:['put away it','put it away','away put it'],a:1,e:'Đại từ đứng giữa.'},{q:'Don’t ___ ! You can do it.',o:['give up','give in to','give out'],a:0,e:'give up = từ bỏ.'}]},
 listen:{dialog:[['A','I can’t find my glasses. I’m looking for them everywhere.','Mình không tìm thấy kính. Mình đang tìm khắp nơi.'],['B','Did you look in your bag?','Bạn tìm trong túi chưa?'],['A','Yes. Oh, wait. I put them on the table.','Rồi. À khoan, mình để chúng trên bàn.'],['B','Turn on the light. It’s too dark here.','Bật đèn lên. Ở đây tối quá.'],['A','Here they are! Thanks for helping me.','Đây rồi! Cảm ơn bạn đã giúp.']],
  qs:[{q:'What is A looking for?',o:['His glasses','His keys','His phone'],a:0,e:'“my glasses”.'},{q:'What does B suggest?',o:['Turn on the light','Call a friend','Go home'],a:0,e:'“Turn on the light.”'}]},
 read:{text:'Last Monday I got up early because I wanted to find out about a new gym. I put on my sports clothes and looked for my bag, but I couldn’t find it. In the end I gave up and took a small one. When I arrived, the trainer picked up my card and turned on the computer. I filled in a form and signed up. It was a good start to the week.',
  qs:[{q:'Why did the writer get up early?',o:['To go to work','To find out about a gym','To cook'],a:1,e:'câu 1.'},{q:'What couldn’t the writer find?',o:['The bag','The card','The form'],a:0,e:'“looked for my bag”.'},{q:'What did the trainer do?',o:['Turned on the computer','Gave up','Put on clothes'],a:0,e:'“turned on the computer”.'}]},
 speak:{shadow:['I’m looking for a new job.','Turn it off, please.'],prompt:'Kể buổi sáng của bạn dùng ít nhất 4 phrasal verbs (get up, put on, turn on, pick up…).'},
 write:{prompt:'Write about your morning routine using at least 5 phrasal verbs (7 sentences).',min:55,model:'I get up at six every day. I turn on the light and put on my clothes. Then I look for my phone and check the news. Sometimes I pick up my sister and take her to school. I never give up my morning coffee. On Sundays I find out about new restaurants and go out with my friends.'}},

{id:'a2u8',lv:'A2',title:'Trạng từ chỉ cách thức, mức độ & tần suất',goal:'Mô tả hành động: như thế nào, mức độ nào, bao lâu một lần.',
 vocab:[['quickly','/ˈkwɪkli/','nhanh','He runs quickly.'],['carefully','/ˈkerfəli/','cẩn thận','Drive carefully.'],['really','/ˈriːəli/','thực sự','I really like it.'],['quite','/kwaɪt/','khá','It’s quite cold.'],['hardly ever','/ˈhɑːrdli ˈevɚ/','hầu như không','I hardly ever eat meat.'],['well','/wel/','tốt (trạng từ)','She speaks English well.'],['fast','/fæst/','nhanh (adj/adv)','He drives fast.'],['too','/tuː/','quá','It’s too expensive.']],
 grammar:{body:'<ul><li><b>Trạng từ cách thức</b>: tính từ + <b>-ly</b> (slow → slowly, careful → carefully). Bất quy tắc: good → <b>well</b>; fast → <b>fast</b>; hard → <b>hard</b>.</li><li><b>Mức độ</b>: very, really, quite, a bit, too (quá mức, nghĩa tiêu cực), enough (đủ): <i>too expensive</i>, <i>not big enough</i>.</li><li><b>Tần suất</b>: always, usually, often, sometimes, hardly ever, never. Đứng <u>trước</u> động từ thường, <u>sau</u> be: <i>She is always late. I never eat meat.</i></li></ul>',
  quiz:[{q:'She sings very ___ .',o:['good','well','goodly'],a:1,e:'Trạng từ của good là well.'},{q:'Drive ___ ! The road is wet.',o:['careful','carefully','care'],a:1,e:'Trạng từ → carefully.'},{q:'He is ___ late for class.',o:['always','always is','is always'],a:0,e:'Trạng từ sau be: He is always late (chọn câu điền: always).'},{q:'This coat is ___ small for me.',o:['too','enough','very much'],a:0,e:'too + adj = quá.'}]},
 listen:{dialog:[['A','Do you cook often?','Bạn có hay nấu ăn không?'],['B','I hardly ever cook. I’m usually too tired.','Mình hầu như không nấu. Mình thường quá mệt.'],['A','Really? I cook quite often.','Thật à? Mình nấu khá thường xuyên.'],['B','You cook well. Your food is really delicious.','Bạn nấu giỏi. Đồ ăn của bạn ngon thật.'],['A','Thanks! Come to my house on Sunday.','Cảm ơn! Chủ nhật qua nhà mình nhé.']],
  qs:[{q:'How often does B cook?',o:['Often','Hardly ever','Every day'],a:1,e:'“hardly ever cook”.'},{q:'Why does B not cook?',o:['He is too tired','He hates food','He has no kitchen'],a:0,e:'“too tired”.'}]},
 read:{text:'Mr Brown is a very careful driver. He always drives slowly and he never uses his phone in the car. His wife drives fast and sometimes she is late. Their son, Tom, hardly ever drives because he lives in the city and he goes everywhere by bike. Tom rides quite well, but he isn’t fast enough to win a race. Last year he practised really hard for one.',
  qs:[{q:'How does Mr Brown drive?',o:['Fast','Slowly and carefully','Badly'],a:1,e:'câu 2.'},{q:'How often does Tom drive?',o:['Every day','Hardly ever','Sometimes'],a:1,e:'“hardly ever drives”.'},{q:'What is true about Tom’s riding?',o:['He isn’t fast enough to win','He is the fastest','He never rides'],a:0,e:'câu 5.'}]},
 speak:{shadow:['She always speaks very clearly.','I hardly ever eat fast food.'],prompt:'Nói về thói quen của bạn và một người thân dùng trạng từ tần suất và cách thức.'},
 write:{prompt:'Describe how you and a family member do daily activities (7 sentences).',min:55,model:'I usually wake up early, but my brother always gets up late. I walk quickly to work, and he walks slowly. I cook quite well, but he hardly ever cooks. He drives too fast, so I never go in his car. My mother speaks softly and she works really hard.'}},

{id:'a2u9',lv:'A2',title:'Viết tin nhắn, thư mời & email thân mật',goal:'Viết thư/tin nhắn ngắn: mời, đồng ý, từ chối, cảm ơn.',
 vocab:[['invitation','/ˌɪnvɪˈteɪʃn/','lời mời','Thanks for the invitation.'],['accept','/əkˈsept/','chấp nhận','I’d love to accept.'],['decline','/dɪˈklaɪn/','từ chối','I’m sorry, I must decline.'],['reply','/rɪˈplaɪ/','trả lời','Please reply by Friday.'],['party','/ˈpɑːrti/','bữa tiệc','Are you coming to the party?'],['regards','/rɪˈɡɑːrdz/','trân trọng','Best regards, Linh.'],['unfortunately','/ʌnˈfɔːrtʃnətli/','tiếc là','Unfortunately, I can’t come.'],['look forward to','/lʊk ˈfɔːrwɚd tuː/','mong chờ','I look forward to seeing you.']],
 grammar:{body:'<ul><li><b>Mở đầu</b>: Hi/Dear Anna, · <b>Kết thúc</b>: See you soon / Best wishes / Regards.</li><li><b>Mời</b>: Would you like to…? / Do you want to…? / I’d like to invite you to… / Why don’t we…?</li><li><b>Đồng ý</b>: I’d love to! / Sure, that sounds great. · <b>Từ chối lịch sự</b>: I’d love to, but I can’t because… / Unfortunately, I’m busy.</li><li><b>Cảm ơn</b>: Thanks for… / Thank you very much for… · <b>look forward to + V-ing</b>.</li></ul>',
  quiz:[{q:'I’m sorry, ___ I can’t come on Saturday.',o:['I’d love to, but','I love, so','because'],a:0,e:'Từ chối lịch sự.'},{q:'I look forward to ___ you.',o:['see','seeing','saw'],a:1,e:'look forward to + V-ing.'},{q:'“Would you like to come to my party?” – “___”',o:['Yes, I’d love to!','Yes, I am.','I don’t have.'],a:0,e:'Đáp lời mời.'},{q:'The best ending for a friendly email is:',o:['Best wishes,','Sincerely yours the manager','Goodbye forever'],a:0,e:'Best wishes phù hợp thân mật.'}]},
 listen:{dialog:[['A','Hi Mai, I’m having a party on Saturday. Would you like to come?','Chào Mai, thứ Bảy mình có tiệc. Bạn đến nhé?'],['B','I’d love to, but I’m visiting my grandmother.','Mình muốn lắm, nhưng mình phải thăm bà.'],['A','That’s a pity. What about Sunday lunch?','Tiếc quá. Vậy bữa trưa Chủ nhật thì sao?'],['B','Sure, that sounds great. What time?','Được, nghe hay đó. Mấy giờ?'],['A','At twelve. I look forward to seeing you!','Mười hai giờ. Mình mong gặp bạn!']],
  qs:[{q:'Why can’t Mai come on Saturday?',o:['She is visiting her grandmother','She is ill','She works'],a:0,e:'“visiting my grandmother”.'},{q:'What do they arrange?',o:['Sunday lunch at 12','Saturday dinner','A film'],a:0,e:'“Sunday lunch … at twelve”.'}]},
 read:{text:'Hi Lan, Thank you very much for your invitation to your wedding. I’m so happy for you and Minh! Unfortunately, I can’t come on 20 June because I have an exam the next day. I’m really sorry. I’ll send you a small present, and I hope we can celebrate together in July. Please give my best wishes to your family. Love, Hoa',
  qs:[{q:'Why can’t Hoa come?',o:['She has an exam','She is abroad','She is ill'],a:0,e:'“I have an exam”.'},{q:'What will Hoa send?',o:['A small present','Flowers','A letter only'],a:0,e:'“send you a small present”.'},{q:'What does Hoa suggest?',o:['Celebrating in July','Moving the wedding','Cancelling the exam'],a:0,e:'“celebrate together in July”.'}]},
 speak:{shadow:['I’d love to, but I’m busy on Saturday.','Thank you very much for inviting me.'],prompt:'Mời một người bạn đi ăn hoặc xem phim; người kia từ chối lịch sự và đề xuất thời gian khác.'},
 write:{prompt:'Write an email declining an invitation and suggesting another time (7 sentences).',min:60,model:'Hi Nam, Thank you very much for inviting me to your birthday party. I’d love to come, but unfortunately I have to work on Saturday evening. I’m really sorry. Could we have dinner together on Sunday instead? I know a nice restaurant near your house. Please let me know if it’s possible. Best wishes, Linh'}},

/* ===== B1 mới ===== */
{id:'b1u7',lv:'B1',title:'Suy đoán & khả năng: may/might/must/can’t, so/such/too/enough',goal:'Suy luận từ bằng chứng; nói mức độ, kết quả.',
 vocab:[['probably','/ˈprɑːbəbli/','có lẽ','It will probably rain.'],['definitely','/ˈdefɪnətli/','chắc chắn','He will definitely come.'],['evidence','/ˈevɪdəns/','bằng chứng','There is no evidence.'],['clue','/kluː/','manh mối','That is a clue.'],['possible','/ˈpɑːsəbl/','có thể','It’s possible.'],['obvious','/ˈɑːbviəs/','rõ ràng','It’s obvious.'],['enough','/ɪˈnʌf/','đủ','Not big enough.'],['tend to','/tend tuː/','có xu hướng','I tend to worry.']],
 grammar:{body:'<ul><li><b>Suy đoán hiện tại</b>: <b>must</b> (chắc chắn đúng) · <b>may/might/could</b> (có thể) · <b>can’t</b> (chắc chắn không). <i>She isn’t answering; she must be asleep. It can’t be true.</i></li><li><b>so + adj</b> (so tired) · <b>such + (a/an) + adj + N</b> (such a long day) · <b>too + adj</b> (quá) · <b>adj + enough</b> (đủ): <i>He’s too young to drive. She’s old enough to vote.</i></li><li>Kết quả: <b>so … that</b> / <b>such … that</b>: <i>It was so hot that we stayed inside.</i></li></ul>',
  quiz:[{q:'The lights are off. They ___ be at home.',o:["can't",'must','should'],a:0,e:'Đoán chắc chắn không (không có đèn).'},{q:'It was ___ a good film that I saw it twice.',o:['so','such','too'],a:1,e:'such a + adj + N.'},{q:'He is ___ young to drive a car.',o:['too','enough','so'],a:0,e:'too young to…'},{q:'She ___ be his sister. They look alike.',o:['might','can’t','mustn’t'],a:0,e:'Có thể – might.'}]},
 listen:{dialog:[['A','Nam isn’t answering his phone.','Nam không nghe điện thoại.'],['B','He must be in a meeting.','Chắc anh ấy đang họp.'],['A','Or he might be on the train; the signal is bad there.','Hoặc có thể đang trên tàu; sóng ở đó yếu.'],['B','He can’t be at home. His car is at the office.','Không thể ở nhà. Xe anh ấy ở văn phòng.'],['A','You’re right. It was such a busy day that he probably forgot.','Bạn nói đúng. Hôm nay bận đến mức chắc anh ấy quên.']],
  qs:[{q:'Where can’t Nam be?',o:['At home','On the train','In a meeting'],a:0,e:'“can’t be at home”.'},{q:'Why does A think Nam forgot?',o:['It was such a busy day','He is ill','He is abroad'],a:0,e:'câu cuối.'}]},
 read:{text:'When the detective entered the room, the window was open and the cup was still warm. “Someone must have been here recently,” he said. A muddy footprint was on the floor. “It can’t be the maid,” he added, “because her shoes are too small.” The witness said the visitor was so tall that he had to bend down. The detective smiled. “It might be the gardener, but I’m not sure yet. We need more evidence.”',
  qs:[{q:'Why does the detective think someone was there recently?',o:['The cup was warm','The door was locked','A phone rang'],a:0,e:'“cup was still warm”.'},{q:'Why can’t it be the maid?',o:['Her shoes are too small','She was abroad','She is tall'],a:0,e:'“shoes are too small”.'},{q:'Does the detective know who it is?',o:['Yes','No, he needs more evidence'],a:1,e:'“might be … not sure”.'}]},
 speak:{shadow:['She must be at work; her car is outside.','It was such a long day that I fell asleep at once.'],prompt:'Nhìn quanh và đoán: ai đó đang ở đâu/đang làm gì, dùng must, might, can’t.'},
 write:{prompt:'Write a short mystery scene (8 sentences) using must, might, can’t, so/such/too/enough.',min:80,model:'The house was so quiet that I felt nervous. The door was open, so someone must have come in. There was a coat on the sofa, but it can’t be mine because it is too big. It might belong to my brother, but he lives abroad. I found a note on the table. It was such a strange message that I read it twice. Someone was clearly trying to tell me something.'}},

{id:'b1u8',lv:'B1',title:'Dạng của động từ: V-ing hay to V',goal:'Chọn đúng dạng động từ sau các động từ thường gặp.',
 vocab:[['enjoy','/ɪnˈdʒɔɪ/','thích','I enjoy reading.'],['avoid','/əˈvɔɪd/','tránh','Avoid making noise.'],['decide','/dɪˈsaɪd/','quyết định','We decided to leave.'],['manage','/ˈmænɪdʒ/','xoay xở','I managed to finish.'],['suggest','/səˈdʒest/','đề nghị','I suggest going early.'],['refuse','/rɪˈfjuːz/','từ chối','He refused to help.'],['keep','/kiːp/','tiếp tục','Keep trying.'],['afford','/əˈfɔːrd/','đủ khả năng','I can’t afford it.']],
 grammar:{body:'<ul><li><b>+ V-ing</b>: enjoy, avoid, suggest, finish, keep, mind, practise, consider · sau giới từ (interested in <b>learning</b>).</li><li><b>+ to V</b>: decide, hope, plan, want, need, manage, refuse, afford, promise, learn.</li><li><b>Cả hai, khác nghĩa</b>: <i>stop doing</i> (dừng) / <i>stop to do</i> (dừng để làm); <i>remember doing</i> (nhớ đã làm) / <i>remember to do</i> (nhớ phải làm).</li><li><b>Sau động từ + tân ngữ + to V</b>: want/ask/tell/allow someone <b>to do</b>: <i>My boss asked me to stay.</i></li></ul>',
  quiz:[{q:'She enjoys ___ novels.',o:['to read','reading','read'],a:1,e:'enjoy + V-ing.'},{q:'They decided ___ a new house.',o:['buying','to buy','buy'],a:1,e:'decide + to V.'},{q:'My boss asked me ___ late.',o:['staying','to stay','stay'],a:1,e:'ask + O + to V.'},{q:'He stopped ___ when he saw the sign. (dừng lại để…)',o:['to look','looking','look'],a:0,e:'stop to do = dừng lại để làm.'}]},
 listen:{dialog:[['A','Did you remember to call the client?','Bạn có nhớ gọi khách hàng không?'],['B','Yes, and I managed to get a good price.','Có, và mình xoay xở được giá tốt.'],['A','I suggest sending the contract today.','Mình đề nghị gửi hợp đồng hôm nay.'],['B','I enjoy working with you. You never avoid making decisions.','Mình thích làm việc với bạn. Bạn không bao giờ né việc ra quyết định.'],['A','Thanks! Let’s keep going.','Cảm ơn! Ta tiếp tục nhé.']],
  qs:[{q:'What did B manage to do?',o:['Get a good price','Cancel the meeting','Change jobs'],a:0,e:'“get a good price”.'},{q:'What does A suggest?',o:['Sending the contract today','Waiting a week','Calling later'],a:0,e:'“suggest sending”.'}]},
 read:{text:'Last year I decided to learn to swim. I had always avoided going near deep water. My sister suggested joining a class, and my teacher promised not to let me sink. At first I refused to put my head under the water, but I kept practising and slowly stopped being afraid. Now I enjoy swimming three times a week. I can’t afford to buy a pool, but I’m planning to visit the sea next summer.',
  qs:[{q:'What did the writer avoid before?',o:['Deep water','Swimming teachers','Exercise'],a:0,e:'“avoided going near deep water”.'},{q:'What did the sister suggest?',o:['Joining a class','Buying a pool','Going to the sea'],a:0,e:'“suggested joining a class”.'},{q:'What is the writer planning?',o:['To visit the sea','To buy a pool','To stop swimming'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['I enjoy learning new languages.','She refused to accept the offer.'],prompt:'Nói về điều bạn đã quyết định, đang cố tránh và thích làm gần đây.'},
 write:{prompt:'Write about a change you decided to make (8 sentences). Use V-ing and to V forms.',min:80,model:'Last month I decided to start running. I had avoided exercise for years because I was afraid of getting tired. My friend suggested running in the park, and I managed to run for ten minutes the first day. I enjoy getting up early now. I keep practising every morning, and I plan to join a race next spring. I can’t afford a personal trainer, but I don’t need one.'}},

{id:'b1u9',lv:'B1',title:'Tiếng Anh công sở: email trang trọng & phỏng vấn',goal:'Viết email trang trọng, trả lời phỏng vấn cơ bản.',
 vocab:[['apply for','/əˈplaɪ fɔːr/','ứng tuyển','I’d like to apply for the job.'],['position','/pəˈzɪʃn/','vị trí','The position is open.'],['experience','/ɪkˈspɪriəns/','kinh nghiệm','I have five years’ experience.'],['qualification','/ˌkwɑːlɪfɪˈkeɪʃn/','bằng cấp','What are your qualifications?'],['strength','/streŋθ/','điểm mạnh','My strength is teamwork.'],['weakness','/ˈwiːknəs/','điểm yếu','My weakness is perfectionism.'],['attach','/əˈtætʃ/','đính kèm','I attach my CV.'],['sincerely','/sɪnˈsɪrli/','trân trọng','Yours sincerely,']],
 grammar:{body:'<ul><li><b>Email trang trọng</b>: <i>Dear Mr/Ms X,</i> · Mở đầu: <i>I am writing to apply for… / to enquire about…</i> · Nội dung: <i>I would be grateful if you could… / Please find attached…</i> · Kết: <i>I look forward to hearing from you. Yours sincerely,</i> (biết tên) / <i>Yours faithfully,</i> (không biết tên).</li><li><b>Trả lời phỏng vấn</b>: cấu trúc <b>Câu trả lời + lý do + ví dụ</b>: <i>My main strength is communication. For example, I…</i></li><li>Dùng <b>would/could</b> cho lịch sự: <i>Could you tell me…? I would like to…</i></li></ul>',
  quiz:[{q:'Formal opening: ___ to apply for the position of accountant.',o:['I am writing','I write you','I’m wanting'],a:0,e:'I am writing to…'},{q:'If you know the person’s name, end with:',o:['Yours sincerely,','Yours faithfully,','Bye,'],a:0,e:'Biết tên → sincerely.'},{q:'“___ you tell me more about the role?”',o:['Could','Do','Are'],a:0,e:'Could you… lịch sự.'},{q:'Please find ___ my CV.',o:['attached','attach','attaching'],a:0,e:'Please find attached.'}]},
 listen:{dialog:[['A','Thank you for coming. Could you tell me about your experience?','Cảm ơn bạn đã đến. Bạn kể về kinh nghiệm được không?'],['B','I’ve worked as an accountant for five years. For example, I managed the budget for three departments.','Tôi làm kế toán năm năm. Ví dụ, tôi quản lý ngân sách cho ba phòng ban.'],['A','What is your main strength?','Điểm mạnh chính của bạn là gì?'],['B','I’m very organised, so I always meet deadlines.','Tôi rất ngăn nắp nên luôn đúng hạn.'],['A','And your weakness?','Còn điểm yếu?'],['B','Sometimes I work too much. I’m learning to delegate.','Đôi khi tôi làm việc quá nhiều. Tôi đang học cách giao việc.']],
  qs:[{q:'How long has B worked as an accountant?',o:['Two years','Five years','Ten years'],a:1,e:'“five years”.'},{q:'What is B’s strength?',o:['Being organised','Speaking fast','Working alone'],a:0,e:'“very organised”.'}]},
 read:{text:'Dear Ms Green, I am writing to apply for the position of Finance Assistant advertised on your website. I have a degree in accounting and two years’ experience in a bank. I am organised, careful and I work well in a team. I would be grateful if you could consider my application. Please find attached my CV. I look forward to hearing from you. Yours sincerely, Linh Tran',
  qs:[{q:'What position is Linh applying for?',o:['Finance Assistant','Manager','Teacher'],a:0,e:'“Finance Assistant”.'},{q:'How much experience does Linh have?',o:['Two years','Five years','None'],a:0,e:'“two years’ experience”.'},{q:'What is attached?',o:['A CV','A photo','A certificate'],a:0,e:'“my CV”.'}]},
 speak:{shadow:['I would like to apply for the position of accountant.','My main strength is that I’m very organised.'],prompt:'Giả lập phỏng vấn: giới thiệu kinh nghiệm, điểm mạnh, điểm yếu (mỗi ý 2–3 câu).'},
 write:{prompt:'Write a formal email applying for a job (9 sentences).',min:90,model:'Dear Mr Smith, I am writing to apply for the position of Accountant advertised on your website. I have a degree in finance and five years’ experience in a manufacturing company. I am responsible for monthly reports and tax declarations. I am careful, organised and good at teamwork. I would be grateful if you could consider my application. Please find attached my CV. I would welcome the opportunity to attend an interview. I look forward to hearing from you. Yours sincerely, Linh Tran'}},

/* ===== B2 mới ===== */
{id:'b2u7',lv:'B2',title:'Nhấn mạnh: so/such, It is … that, What I need is …',goal:'Làm nổi bật ý bằng cấu trúc chẻ (cleft) và nhấn mạnh.',
 vocab:[['emphasise','/ˈemfəsaɪz/','nhấn mạnh','I want to emphasise this point.'],['essential','/ɪˈsenʃl/','thiết yếu','Sleep is essential.'],['precisely','/prɪˈsaɪsli/','chính xác','That’s precisely why.'],['merely','/ˈmɪrli/','chỉ đơn thuần','It’s merely a rumour.'],['indeed','/ɪnˈdiːd/','thật vậy','It was indeed a success.'],['what matters','/wɑːt ˈmætɚz/','điều quan trọng','What matters is honesty.'],['in fact','/ɪn ˈfækt/','thực tế là','In fact, I disagree.'],['above all','/əˌbʌv ˈɔːl/','trên hết','Above all, be honest.']],
 grammar:{body:'<ul><li><b>Cleft với It is/was … that/who</b>: nhấn mạnh thành phần. <i>It was Mai <b>who</b> solved the problem. It is <b>quality</b> that matters.</i></li><li><b>Cleft với What</b>: <i>What I need is a holiday. What surprised me was the price.</i></li><li><b>All/The thing/The reason … is</b>: <i>The reason I called is to say thanks.</i></li><li><b>Do/does/did nhấn mạnh</b>: <i>I <b>do</b> understand. She <b>did</b> warn us.</i></li></ul>',
  quiz:[{q:'It was Mai ___ solved the problem.',o:['who','what','which'],a:0,e:'It was + người + who.'},{q:'___ I need is a long holiday.',o:['That','What','It'],a:1,e:'What I need is…'},{q:'I ___ understand your concern, but we can’t change it.',o:['do','am','have'],a:0,e:'do nhấn mạnh động từ.'},{q:'It is honesty ___ matters most.',o:['that','what','who'],a:0,e:'It is + N + that.'}]},
 listen:{dialog:[['A','Why did the project succeed?','Vì sao dự án thành công?'],['B','It was the team that made the difference.','Chính đội ngũ đã tạo nên khác biệt.'],['A','What was the biggest challenge?','Thách thức lớn nhất là gì?'],['B','What worried me most was the budget.','Điều làm tôi lo nhất là ngân sách.'],['A','And what do you need now?','Và giờ bạn cần gì?'],['B','What I need is a few days off, to be honest.','Điều tôi cần là vài ngày nghỉ, nói thật.']],
  qs:[{q:'What made the difference?',o:['The team','The budget','The client'],a:0,e:'“It was the team that…”.'},{q:'What does B need now?',o:['A few days off','More money','A new team'],a:0,e:'câu cuối.'}]},
 read:{text:'Many people believe that talent is what makes someone successful. In fact, it is often hard work that counts. Research shows that it is not the number of hours but the quality of practice that matters. What most successful people share is the habit of learning from failure. The reason they improve is not that they never fail; it is that they analyse every mistake. Above all, they are patient. As one coach said, “I do believe anyone can succeed if they keep going.”',
  qs:[{q:'According to the text, what often counts?',o:['Hard work','Talent','Luck'],a:0,e:'“it is often hard work that counts”.'},{q:'What do successful people share?',o:['Learning from failure','Never failing','High salaries'],a:0,e:'“habit of learning from failure”.'},{q:'What does the coach believe?',o:['Anyone can succeed if they keep going','Only talent matters','Practice is useless'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['What I really need is more time to prepare.','It was my teacher who inspired me to study English.'],prompt:'Nêu điều quan trọng nhất trong thành công/học tập, dùng “What matters is…” và “It is … that…”.'},
 write:{prompt:'Write a paragraph emphasising what matters most in learning a language (8 sentences).',min:90,model:'Many people think that learning a language requires talent. In fact, it is consistency that matters most. What surprised me was how quickly I improved after I started studying every day. The reason I succeeded is not that I was gifted; it is that I never gave up. I do believe that speaking regularly is essential. Above all, learners should be patient with themselves.'}},

{id:'b2u8',lv:'B2',title:'Mệnh đề quan hệ nâng cao & rút gọn mệnh đề',goal:'Nối và rút gọn câu để viết súc tích.',
 vocab:[['whereby','/werˈbaɪ/','theo đó (qua đó)','A system whereby staff share ideas.'],['whose','/huːz/','của người/vật mà','The man whose car was stolen.'],['inhabitant','/ɪnˈhæbɪtənt/','cư dân','The inhabitants were friendly.'],['founded','/ˈfaʊndɪd/','được thành lập','The company was founded in 1990.'],['leading','/ˈliːdɪŋ/','hàng đầu','A leading bank.'],['renowned','/rɪˈnaʊnd/','nổi tiếng','A renowned architect.'],['based on','/ˈbeɪst ɑːn/','dựa trên','A film based on a true story.'],['consisting of','/kənˈsɪstɪŋ əv/','bao gồm','A team consisting of five people.']],
 grammar:{body:'<ul><li><b>Giới từ + whom/which</b> (trang trọng): <i>The person <b>to whom</b> I spoke… · The way <b>in which</b> it works…</i></li><li><b>which</b> bổ nghĩa cả mệnh đề: <i>He passed, <b>which</b> surprised everyone.</i></li><li><b>Rút gọn bằng V-ing</b> (chủ động): <i>The man <b>standing</b> there = who is standing there.</i></li><li><b>Rút gọn bằng V3</b> (bị động): <i>The report <b>written</b> by Ann = which was written by Ann.</i></li><li><b>Mệnh đề phân từ đầu câu</b>: <i><b>Having finished</b> the report, she left.</i></li></ul>',
  quiz:[{q:'The woman ___ next to me is a lawyer.',o:['sitting','sat','was sit'],a:0,e:'Rút gọn chủ động → V-ing.'},{q:'The book ___ by Tom became a bestseller.',o:['writing','written','wrote'],a:1,e:'Rút gọn bị động → V3.'},{q:'The person ___ I spoke was very helpful.',o:['to whom','which','whose'],a:0,e:'to whom (trang trọng).'},{q:'He passed the exam, ___ surprised everyone.',o:['which','that','what'],a:0,e:'which bổ nghĩa cả mệnh đề.'}]},
 listen:{dialog:[['A','Who is the man standing by the door?','Người đàn ông đứng cạnh cửa là ai?'],['B','That’s Mr Lee, the architect whose designs won the prize.','Đó là ông Lee, kiến trúc sư có thiết kế đoạt giải.'],['A','The building designed by him is amazing.','Tòa nhà do ông thiết kế thật tuyệt.'],['B','Yes, it’s a project based on green technology.','Ừ, đó là dự án dựa trên công nghệ xanh.'],['A','Having seen it, I’d love to meet him.','Đã xem rồi, mình rất muốn gặp ông.']],
  qs:[{q:'Who is Mr Lee?',o:['An architect','A teacher','A driver'],a:0,e:'“the architect”.'},{q:'What is the project based on?',o:['Green technology','Old designs','Traditional art'],a:0,e:'“based on green technology”.'}]},
 read:{text:'Founded in 1995, our company has become a leading supplier of solar panels. The products manufactured in our factory are exported to twenty countries. Our engineers, many of whom studied abroad, have developed a system whereby energy is stored during the day. Having invested heavily in research, we now offer prices that are lower than those of competitors. The customers using our systems save up to forty per cent on electricity, which explains our rapid growth.',
  qs:[{q:'When was the company founded?',o:['1985','1995','2005'],a:1,e:'“Founded in 1995”.'},{q:'What does the system do?',o:['Stores energy during the day','Sells cars','Cleans water'],a:0,e:'“energy is stored during the day”.'},{q:'How much can customers save?',o:['Up to 40%','Up to 10%','Up to 90%'],a:0,e:'“up to forty per cent”.'}]},
 speak:{shadow:['The man standing over there is my manager.','Having finished the report, I went home.'],prompt:'Giới thiệu công ty/trường của bạn bằng câu có mệnh đề quan hệ và mệnh đề rút gọn.'},
 write:{prompt:'Write a company or city profile (9 sentences) using relative clauses and participle clauses.',min:90,model:'Founded in 2008, our company has become a leading provider of accounting software. The products developed by our team are used by more than 5,000 businesses. Our engineers, most of whom have worked abroad, focus on simple design. Having listened to customers, we introduced a system whereby reports are created automatically. Customers using the system save several hours a week, which explains our rapid growth.'}},

{id:'b2u9',lv:'B2',title:'Thảo luận & tranh luận (kiểu IELTS Speaking Part 3)',goal:'Nêu, bảo vệ, phản biện quan điểm; so sánh và dự đoán.',
 vocab:[['perspective','/pɚˈspektɪv/','góc nhìn','From my perspective…'],['viewpoint','/ˈvjuːpɔɪnt/','quan điểm','I understand your viewpoint.'],['argue','/ˈɑːrɡjuː/','lập luận','Some argue that…'],['convince','/kənˈvɪns/','thuyết phục','I’m not convinced.'],['point out','/ˌpɔɪnt ˈaʊt/','chỉ ra','Let me point out a problem.'],['on the contrary','/ɑːn ðə ˈkɑːntreri/','ngược lại','On the contrary, it’s cheaper.'],['it depends','/ɪt dɪˈpendz/','tùy','It depends on the person.'],['to some extent','/tuː sʌm ɪkˈstent/','ở một mức độ nào đó','To some extent, I agree.']],
 grammar:{body:'<ul><li><b>Nêu ý kiến</b>: <i>From my perspective… / As far as I’m concerned… / I’d say that…</i></li><li><b>Đồng ý một phần</b>: <i>I see your point, but… / To some extent, yes, however… / That’s partly true.</i></li><li><b>Phản đối lịch sự</b>: <i>I’m not sure I agree. / I’d argue that… / On the contrary…</i></li><li><b>Dự đoán/so sánh</b>: <i>It’s likely that… / In the future, we will probably… / Compared with the past…</i></li><li><b>Cấu trúc trả lời</b>: Ý kiến → lý do → ví dụ → (đối lập) → kết luận ngắn.</li></ul>',
  quiz:[{q:'“Technology makes life easier.” – “___ , it also creates new problems.”',o:['To some extent, yes; however,','Of course not,','That is a nothing,'],a:0,e:'Đồng ý một phần rồi phản biện.'},{q:'Which phrase gives an opinion?',o:['As far as I’m concerned,','Once upon a time,','By the way,'],a:0,e:'As far as I’m concerned = theo tôi.'},{q:'“I’d ___ that education is more important than money.”',o:['argue','say to','tell'],a:0,e:'I’d argue that…'},{q:'“Do people spend too much?” – “___ on the person.”',o:['It depends','It must','It should'],a:0,e:'It depends on…'}]},
 listen:{dialog:[['A','Do you think people should work fewer hours?','Bạn có nghĩ mọi người nên làm ít giờ hơn không?'],['B','To some extent, yes. From my perspective, long hours reduce productivity.','Ở mức độ nào đó thì có. Theo tôi, làm nhiều giờ làm giảm năng suất.'],['A','But some jobs require long hours.','Nhưng một số công việc đòi hỏi nhiều giờ.'],['B','That’s true, however, employers could offer flexibility.','Đúng, tuy nhiên nhà tuyển dụng có thể linh hoạt hơn.'],['A','It depends on the industry, I suppose.','Tôi nghĩ còn tùy ngành.']],
  qs:[{q:'What is B’s opinion?',o:['Long hours reduce productivity','People should work more','Nothing should change'],a:0,e:'câu 2.'},{q:'What does B suggest?',o:['Flexibility from employers','Higher salaries','Longer breaks'],a:0,e:'“employers could offer flexibility”.'}]},
 read:{text:'Should university education be free? Supporters argue that free education would give everyone equal opportunities and reduce debt. As far as they are concerned, society benefits when more people are well educated. However, critics point out that the cost would be enormous, and taxpayers who never attend university might object. To some extent, both views have merit. It probably depends on how a country balances its budget. On balance, a system offering grants to poorer students may be the fairest.',
  qs:[{q:'What do supporters argue?',o:['It gives equal opportunities','It is too expensive','It lowers quality'],a:0,e:'câu 2.'},{q:'What do critics point out?',o:['The cost would be enormous','Students are lazy','Universities are bad'],a:0,e:'“cost would be enormous”.'},{q:'What does the writer conclude?',o:['Grants for poorer students may be fairest','Education must be free','Education must be expensive'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['From my perspective, flexibility is more important than salary.','I see your point, but I’d argue that it depends.'],prompt:'Trả lời trong 1 phút: “Is it better to live in a city or in the countryside?” theo cấu trúc ý kiến – lý do – ví dụ – đối lập.'},
 write:{prompt:'Write a discussion paragraph: “Should children have smartphones?” (10 sentences, both views + your opinion).',min:110,model:'Whether children should have smartphones is a widely debated issue. Supporters argue that phones keep children safe and help them learn. As far as they are concerned, technology is an essential skill. However, critics point out that excessive screen time may harm concentration and sleep. To some extent, both views are valid. From my perspective, it depends on the child’s age and on parental supervision. On balance, I believe that limited use with clear rules is the best approach.'}},

/* ===== C1 ===== */
{id:'c1u1',lv:'C1',title:'Đảo ngữ & cấu trúc nhấn mạnh nâng cao',goal:'Dùng đảo ngữ với trạng từ phủ định để nhấn mạnh trong văn viết trang trọng.',
 vocab:[['hardly','/ˈhɑːrdli/','hầu như không','Hardly had he left when it rained.'],['seldom','/ˈseldəm/','hiếm khi','Seldom do we see such talent.'],['rarely','/ˈrerli/','hiếm khi','Rarely has he been so angry.'],['not only','/nɑːt ˈoʊnli/','không những','Not only did she win…'],['under no circumstances','/ˈʌndɚ noʊ ˈsɝːkəmstænsɪz/','trong mọi hoàn cảnh cũng không','Under no circumstances open it.'],['no sooner','/noʊ ˈsuːnɚ/','vừa mới … thì','No sooner had I arrived than…'],['scarcely','/ˈskersli/','hầu như không','Scarcely had they begun…'],['little did','/ˈlɪtl dɪd/','hoàn toàn không biết','Little did I know…']],
 grammar:{body:'<p><b>Đảo ngữ</b> (trợ động từ đứng trước chủ ngữ) sau trạng từ phủ định/hạn chế đặt ở đầu câu — văn viết trang trọng, nhấn mạnh.</p><ul><li><b>Never / Rarely / Seldom / Hardly ever</b> + trợ từ + S + V: <i>Rarely <b>have I seen</b> such a view.</i></li><li><b>Not only … but also</b>: <i>Not only <b>did she</b> pass, but she also got the top mark.</i></li><li><b>No sooner … than / Hardly … when</b> (dùng past perfect): <i>No sooner <b>had I sat down</b> than the phone rang.</i></li><li><b>Under no circumstances / On no account</b>: <i>Under no circumstances <b>should you</b> share your password.</i></li><li><b>Little did</b> + S + V: <i>Little did he know that…</i></li></ul>',
  quiz:[{q:'Never ___ such a beautiful place.',o:['I have seen','have I seen','I saw'],a:1,e:'Never + đảo ngữ.'},{q:'No sooner had she arrived ___ it started to rain.',o:['when','than','then'],a:1,e:'No sooner … than.'},{q:'Not only ___ late, but he also forgot the documents.',o:['he was','was he','he is'],a:1,e:'Not only + đảo ngữ.'},{q:'Under no circumstances ___ the door.',o:['you should open','should you open','you open'],a:1,e:'Under no circumstances + đảo ngữ.'}]},
 listen:{dialog:[['A','Did you enjoy the lecture?','Bạn có thích bài giảng không?'],['B','Rarely have I heard such a clear explanation.','Hiếm khi mình nghe được lời giải thích rõ ràng như vậy.'],['A','Not only was it clear, but it was also funny.','Không những rõ ràng mà còn hài hước.'],['B','No sooner had she started than everyone was listening.','Vừa bắt đầu là mọi người đã chăm chú nghe.'],['A','Little did we know she would be so good.','Chúng ta đã không biết cô ấy giỏi như vậy.']],
  qs:[{q:'What did B think of the lecture?',o:['Very clear','Boring','Too fast'],a:0,e:'“such a clear explanation”.'},{q:'Was it funny?',o:['Yes','No'],a:0,e:'“also funny”.'}]},
 read:{text:'Seldom has a company grown so quickly. Not only did it double its profits within a year, but it also expanded to twelve new markets. No sooner had the founders announced the plan than investors began to call. Hardly had the first shop opened when queues formed outside. Under no circumstances, the founders insisted, would quality be sacrificed for speed. Little did they realise how difficult maintaining that promise would become.',
  qs:[{q:'What is unusual about the company?',o:['It grew very quickly','It closed shops','It changed its name'],a:0,e:'“Seldom has a company grown so quickly”.'},{q:'What did the founders insist on?',o:['Quality must not be sacrificed','Speed above all','Lower prices'],a:0,e:'“Under no circumstances… quality”.'},{q:'What is implied at the end?',o:['Keeping the promise would be hard','Everything was easy','They sold the company'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['Rarely have I felt so proud of a team.','No sooner had I finished than the next task arrived.'],prompt:'Kể một trải nghiệm bất ngờ dùng ít nhất 3 cấu trúc đảo ngữ (Never…, Not only…, No sooner…).'},
 write:{prompt:'Write a short formal announcement (9 sentences) using at least 4 inversion structures.',min:100,model:'Rarely has our company faced such a challenging year. Not only did sales fall, but costs also increased. No sooner had we solved one problem than another appeared. Under no circumstances will we reduce staff training. Seldom have I seen a team work so closely. Little did we realise how strong we had become. Hardly had the season ended when new orders arrived. Never before have we been so optimistic about the future.'}},

{id:'c1u2',lv:'C1',title:'Giả định cách (subjunctive) & cấu trúc “It’s time / I’d rather / suppose”',goal:'Diễn đạt yêu cầu, đề xuất, mong muốn với cấu trúc trang trọng.',
 vocab:[['insist','/ɪnˈsɪst/','khăng khăng','She insisted that he apologise.'],['demand','/dɪˈmænd/','yêu cầu (mạnh)','They demanded that it be changed.'],['recommend','/ˌrekəˈmend/','đề nghị','I recommend that he see a doctor.'],['essential','/ɪˈsenʃl/','thiết yếu','It’s essential that she be present.'],['as if','/æz ˈɪf/','như thể','He talks as if he knew everything.'],['high time','/haɪ ˈtaɪm/','đã đến lúc','It’s high time we left.'],['would rather','/wʊd ˈræðɚ/','thà … hơn','I’d rather you didn’t.'],['suppose','/səˈpoʊz/','giả sử','Suppose you won…']],
 grammar:{body:'<ul><li><b>Subjunctive</b> (V nguyên mẫu, không chia) sau <b>insist, demand, recommend, suggest, propose, require</b> + that: <i>I suggest that he <b>be</b> present. They require that every student <b>submit</b> the form.</i> Tương tự với <b>It is essential/vital/important that…</b>.</li><li><b>It’s (high) time + S + V-ed</b> (quá khứ, nghĩa hiện tại): <i>It’s time we <b>left</b>.</i></li><li><b>would rather + S + V-ed</b>: <i>I’d rather you <b>stayed</b>.</i></li><li><b>as if / as though</b> + past (không có thật): <i>He behaves as if he <b>were</b> the boss.</i></li><li><b>Suppose / Supposing</b> + past: <i>Suppose you <b>had</b> a million dollars?</i></li></ul>',
  quiz:[{q:'I suggest that he ___ a doctor.',o:['sees','see','saw'],a:1,e:'Subjunctive: see (không chia).'},{q:'It’s high time we ___ home.',o:['go','went','will go'],a:1,e:'It’s time + S + V-ed.'},{q:'I’d rather you ___ smoke here.',o:["don't","didn't",'not'],a:1,e:'would rather + S + past.'},{q:'He talks as if he ___ everything.',o:['knows','knew','will know'],a:1,e:'as if + past (không có thật).'}]},
 listen:{dialog:[['A','The manager insisted that everyone attend the meeting.','Quản lý yêu cầu mọi người phải dự họp.'],['B','I’d rather she asked us politely.','Mình thà cô ấy nhờ lịch sự hơn.'],['A','It’s high time she changed her style.','Đã đến lúc cô ấy đổi phong cách.'],['B','She behaves as if she owned the company.','Cô ấy cư xử như thể là chủ công ty.'],['A','Suppose she left. Who would replace her?','Giả sử cô ấy rời đi. Ai sẽ thay?']],
  qs:[{q:'What did the manager insist on?',o:['Everyone attend the meeting','Everyone leave','Everyone work late'],a:0,e:'“insisted that everyone attend”.'},{q:'What does B prefer?',o:['That she asked politely','That she shouted','That she left'],a:0,e:'“I’d rather she asked us politely”.'}]},
 read:{text:'The committee recommended that the city introduce a congestion charge. It is essential that the money be spent on public transport, the report stressed. Some residents would rather the council invested in roads. They argue that it’s high time the government listened to drivers. Critics of the scheme act as if car owners were the only people affected. Suppose the charge were introduced tomorrow: buses would probably need to run more often.',
  qs:[{q:'What did the committee recommend?',o:['A congestion charge','More roads','A ban on cars'],a:0,e:'“introduce a congestion charge”.'},{q:'What is essential according to the report?',o:['Money be spent on public transport','Taxes be cut','Cars be free'],a:0,e:'câu 2.'},{q:'What would some residents prefer?',o:['Investment in roads','No buses','A higher charge'],a:0,e:'“invested in roads”.'}]},
 speak:{shadow:['I’d rather you told me the truth.','It’s high time we reviewed the budget.'],prompt:'Đưa lời khuyên/yêu cầu trang trọng cho một dự án dùng: suggest that…, It’s essential that…, I’d rather…'},
 write:{prompt:'Write formal recommendations for improving your workplace (9 sentences) using subjunctive structures.',min:100,model:'I recommend that the company introduce flexible working hours. It is essential that every employee receive regular feedback. Management should insist that meetings begin on time. It’s high time we updated our software. I would rather the budget were used for training than for decoration. Some managers act as if deadlines were optional; it is vital that this attitude change. Suppose the company adopted these changes: productivity would probably improve.'}},

{id:'c1u3',lv:'C1',title:'Danh hóa (nominalisation) & văn phong học thuật',goal:'Chuyển động từ/tính từ thành danh từ để viết súc tích, trang trọng.',
 vocab:[['implementation','/ˌɪmplɪmenˈteɪʃn/','sự triển khai','The implementation took a year.'],['consumption','/kənˈsʌmpʃn/','sự tiêu thụ','Energy consumption is rising.'],['decline','/dɪˈklaɪn/','sự suy giảm','A decline in sales.'],['awareness','/əˈwernəs/','nhận thức','Public awareness has grown.'],['availability','/əˌveɪləˈbɪləti/','sự sẵn có','Availability of data is limited.'],['reluctance','/rɪˈlʌktəns/','sự miễn cưỡng','There is reluctance to change.'],['contribution','/ˌkɑːntrɪˈbjuːʃn/','sự đóng góp','A major contribution.'],['emergence','/ɪˈmɝːdʒəns/','sự xuất hiện','The emergence of new firms.']],
 grammar:{body:'<p><b>Nominalisation</b> = biến động từ/tính từ thành danh từ để câu trang trọng, đặc trưng văn học thuật.</p><ul><li>decide → <b>decision</b> · improve → <b>improvement</b> · fail → <b>failure</b> · available → <b>availability</b> · aware → <b>awareness</b> · grow → <b>growth</b>.</li><li>Thông thường: <i>Prices <b>rose</b> quickly, so people bought less.</i> → Học thuật: <i>A <b>rapid rise</b> in prices led to a <b>reduction</b> in consumption.</i></li><li>Cụm hay dùng: <i>lead to, result in, contribute to, be attributed to, give rise to, a growing awareness of, a decline in.</i></li><li>Tránh động từ mơ hồ (get, do, thing); ưu tiên danh từ trừu tượng + động từ trang trọng.</li></ul>',
  quiz:[{q:'Nominalise: “Prices rose quickly.” → A quick ___ in prices.',o:['rise','rising','risen'],a:0,e:'rise (danh từ).'},{q:'“The government decided to act.” → The government’s ___ to act.',o:['decision','decide','decided'],a:0,e:'decision.'},{q:'A decline ___ sales was reported.',o:['of','in','on'],a:1,e:'a decline in…'},{q:'Which sentence is more academic?',o:['Lots of people got interested in health.','A growing awareness of health has led to changes in consumption.','People care about health now a lot.'],a:1,e:'Dùng danh hóa và cụm học thuật.'}]},
 listen:{dialog:[['A','How should I rewrite “More people are using phones, so shops are closing”?','Mình nên viết lại câu này thế nào?'],['B','You could say: the increased use of phones has contributed to the closure of shops.','Bạn có thể viết: việc sử dụng điện thoại tăng đã góp phần khiến cửa hàng đóng cửa.'],['A','That sounds more academic.','Nghe học thuật hơn.'],['B','Yes. Nominalisation makes writing concise and formal.','Đúng. Danh hóa làm văn súc tích và trang trọng.'],['A','I’ll use it in my essay.','Mình sẽ dùng trong bài luận.']],
  qs:[{q:'What does B suggest?',o:['Using nominalisation','Writing shorter sentences only','Avoiding nouns'],a:0,e:'“Nominalisation makes writing concise and formal.”'},{q:'What has phones’ use contributed to?',o:['The closure of shops','Higher prices','More jobs'],a:0,e:'“closure of shops”.'}]},
 read:{text:'The rapid emergence of online platforms has led to a significant decline in high-street retail. This shift is attributed largely to the availability of cheaper goods and the convenience of home delivery. However, the reluctance of older consumers to adopt digital payment methods has slowed the transition in some regions. A growing awareness of environmental costs has also given rise to calls for regulation of packaging. Ultimately, the contribution of technology to economic growth must be weighed against its social consequences.',
  qs:[{q:'What has caused the decline in high-street retail?',o:['The emergence of online platforms','Higher rents','Fewer customers'],a:0,e:'câu 1.'},{q:'Who has slowed the transition?',o:['Older consumers reluctant to adopt digital payments','Young people','Governments'],a:0,e:'“reluctance of older consumers”.'},{q:'What must be weighed against technology’s contribution?',o:['Its social consequences','Its price','Its speed'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['A rapid rise in prices has led to a reduction in consumption.','There is a growing awareness of environmental issues.'],prompt:'Mô tả một xu hướng xã hội (giá nhà, giao thông, mạng xã hội) dùng ít nhất 4 danh từ trừu tượng.'},
 write:{prompt:'Rewrite this in academic style, then write 8 sentences on a social trend: “More people live in cities, so houses cost more and roads are busy.”',min:100,model:'The increase in urban populations has resulted in a rise in housing costs and a growth in traffic congestion. A growing awareness of these problems has led to calls for investment in public transport. However, the availability of affordable housing remains limited. The reluctance of authorities to regulate rents has contributed to the situation. The emergence of remote work may reduce demand for city centres in the long term.'}},

{id:'c1u4',lv:'C1',title:'Thành ngữ, collocation & cụm động từ nâng cao',goal:'Dùng tự nhiên các cụm từ cố định trong nói và viết.',
 vocab:[['break the ice','/breɪk ði ˈaɪs/','phá vỡ sự ngại ngùng','A joke can break the ice.'],['on the same page','/ɑːn ðə seɪm ˈpeɪdʒ/','đồng thuận, hiểu như nhau','Let’s make sure we’re on the same page.'],['a blessing in disguise','/ə ˈblesɪŋ ɪn dɪsˈɡaɪz/','trong cái rủi có cái may','Losing that job was a blessing in disguise.'],['under pressure','/ˈʌndɚ ˈpreʃɚ/','chịu áp lực','He works well under pressure.'],['meet the deadline','/miːt ðə ˈdedlaɪn/','kịp hạn chót','We must meet the deadline.'],['carry out','/ˈkæri aʊt/','thực hiện','They carried out a survey.'],['come up with','/ˌkʌm ˈʌp wɪð/','nghĩ ra','She came up with a solution.'],['put up with','/ˌpʊt ˈʌp wɪð/','chịu đựng','I can’t put up with the noise.']],
 grammar:{body:'<ul><li><b>Collocation</b> (từ hay đi cùng nhau): <i>make a decision (✗ do a decision), take a risk, heavy rain, strong coffee, reach an agreement, raise awareness, meet a deadline, draw a conclusion.</i></li><li><b>Thành ngữ</b>: <i>break the ice, on the same page, a blessing in disguise, the tip of the iceberg, back to square one, hit the nail on the head.</i></li><li><b>Phrasal verb 3 từ</b> (không tách): <i>come up with, put up with, look forward to, get away with, run out of, keep up with.</i></li><li>Lưu ý: dùng thành ngữ vừa phải; phù hợp ngữ cảnh (nói &gt; viết học thuật).</li></ul>',
  quiz:[{q:'We need to ___ a decision by Friday.',o:['do','make','take on'],a:1,e:'make a decision.'},{q:'She ___ a brilliant idea for the project.',o:['came up with','came in for','came across'],a:0,e:'come up with = nghĩ ra.'},{q:'I can’t ___ his rude behaviour any longer.',o:['put up with','put off','put out'],a:0,e:'put up with = chịu đựng.'},{q:'Losing the contract was a blessing ___ .',o:['in disguise','in secret','in fact'],a:0,e:'a blessing in disguise.'}]},
 listen:{dialog:[['A','Are we on the same page about the schedule?','Ta đã thống nhất về lịch chưa?'],['B','I think so. We must meet the deadline, whatever happens.','Mình nghĩ rồi. Ta phải kịp hạn chót, dù thế nào.'],['A','Someone needs to come up with a plan B.','Cần ai đó nghĩ ra phương án B.'],['B','I’ll carry out a risk review. It could be a blessing in disguise.','Mình sẽ thực hiện rà soát rủi ro. Có thể là trong cái rủi có cái may.'],['A','Great. I can’t put up with more delays.','Tuyệt. Mình không chịu nổi thêm chậm trễ.']],
  qs:[{q:'What must they do?',o:['Meet the deadline','Cancel the project','Hire staff'],a:0,e:'“meet the deadline”.'},{q:'What will B do?',o:['Carry out a risk review','Make a call','Change jobs'],a:0,e:'“carry out a risk review”.'}]},
 read:{text:'When our start-up lost its biggest client, we felt we were back to square one. Under pressure to survive, the team came up with a new plan: instead of one large customer, we would look for many small ones. At first we struggled to break the ice with unfamiliar markets, but a series of short surveys we carried out hit the nail on the head about what customers really needed. In hindsight, losing that contract was a blessing in disguise. Two years later, revenue is three times higher.',
  qs:[{q:'What did the team do after losing the client?',o:['Came up with a new plan','Closed the company','Raised prices'],a:0,e:'“came up with a new plan”.'},{q:'What helped them understand customers?',o:['Short surveys','Advertising','A merger'],a:0,e:'“short surveys we carried out”.'},{q:'How do they view losing the contract now?',o:['A blessing in disguise','A disaster','Unimportant'],a:0,e:'“blessing in disguise”.'}]},
 speak:{shadow:['We need to make sure we’re on the same page.','It turned out to be a blessing in disguise.'],prompt:'Kể một khó khăn trong công việc và cách bạn “come up with” giải pháp, dùng ≥3 cụm cố định.'},
 write:{prompt:'Write a reflective paragraph (9 sentences) about a setback that became an opportunity. Use at least 5 idioms/collocations/phrasal verbs.',min:100,model:'When I was told that my project would be cancelled, I felt I was back to square one. Under pressure to find a new role, I came up with a proposal for a smaller team. At the first meeting I tried to break the ice with a simple question. It turned out to be a blessing in disguise: I learned new skills and made a bigger contribution. I still make a habit of reflecting on my mistakes. I can no longer put up with wasting time, so I now meet every deadline in advance.'}},

{id:'c1u5',lv:'C1',title:'Cấu trúc chẻ & đảo trật tự từ để nhấn mạnh (fronting)',goal:'Điều chỉnh trọng tâm câu để mạch lạc và có chủ đích.',
 vocab:[['crucial','/ˈkruːʃl/','then chốt','It’s crucial to plan.'],['pinpoint','/ˈpɪnpɔɪnt/','xác định chính xác','We must pinpoint the problem.'],['underlying','/ˌʌndɚˈlaɪɪŋ/','cơ bản, nằm bên dưới','The underlying cause is cost.'],['emerge','/ɪˈmɝːdʒ/','xuất hiện','New trends emerge.'],['consequently','/ˈkɑːnsɪkwentli/','do đó','Consequently, sales fell.'],['thereby','/ðerˈbaɪ/','nhờ đó','Thereby reducing risk.'],['albeit','/ɔːlˈbiːɪt/','mặc dù','A slow, albeit steady, recovery.'],['whereas','/werˈæz/','trong khi','Whereas A rose, B fell.']],
 grammar:{body:'<ul><li><b>Cleft (It-cleft)</b>: <i>It was <b>in 2020</b> that everything changed.</i></li><li><b>Pseudo-cleft (What-cleft)</b>: <i>What we need to pinpoint is the underlying cause.</i></li><li><b>Reverse pseudo-cleft</b>: <i>The underlying cause is what we need to pinpoint.</i></li><li><b>Fronting</b> (đưa thành phần lên đầu): <i><b>Particularly striking</b> was the fall in prices. <b>Central to the plan</b> is trust.</i></li><li><b>Liên kết trang trọng</b>: <i>thereby + V-ing, albeit + adj, whereas.</i></li></ul>',
  quiz:[{q:'It was in 2020 ___ everything changed.',o:['that','what','which'],a:0,e:'It was + thời gian + that.'},{q:'___ we need to pinpoint is the underlying cause.',o:['What','That','It'],a:0,e:'What-cleft.'},{q:'Particularly striking ___ the fall in prices.',o:['was','were','is being'],a:0,e:'Fronting: was + chủ ngữ.'},{q:'The plan reduces costs, ___ increasing efficiency.',o:['thereby','whereas','albeit'],a:0,e:'thereby + V-ing.'}]},
 listen:{dialog:[['A','What is the real problem here?','Vấn đề thực sự ở đây là gì?'],['B','What we need to pinpoint is the underlying cause of the delays.','Điều ta cần xác định là nguyên nhân gốc của sự chậm trễ.'],['A','It was last month that the problems began.','Chính từ tháng trước các vấn đề bắt đầu.'],['B','Crucial to the solution is better communication.','Then chốt của giải pháp là giao tiếp tốt hơn.'],['A','Agreed. Improving it would reduce delays, albeit slowly.','Đồng ý. Cải thiện nó sẽ giảm chậm trễ, dù chậm.']],
  qs:[{q:'What do they need to pinpoint?',o:['The underlying cause','The price','The client'],a:0,e:'“the underlying cause”.'},{q:'What is crucial to the solution?',o:['Better communication','More staff','New software'],a:0,e:'“Crucial … is better communication”.'}]},
 read:{text:'What distinguishes successful organisations is not the size of their budgets but the quality of their decisions. It was during the financial crisis that many firms discovered how fragile their strategies were. Central to recovery was a willingness to change. Some companies restructured quickly, thereby saving jobs, albeit at the cost of short-term profit, whereas others delayed and lost market share. What emerged from this period was a new respect for flexibility.',
  qs:[{q:'What distinguishes successful organisations?',o:['Quality of decisions','Size of budgets','Number of staff'],a:0,e:'câu 1.'},{q:'When did firms discover their weaknesses?',o:['During the financial crisis','After 2030','Before the war'],a:0,e:'“It was during the financial crisis that…”.'},{q:'What emerged after the crisis?',o:['A new respect for flexibility','A ban on change','Lower taxes'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['What distinguishes good managers is their ability to listen.','Central to our success is teamwork.'],prompt:'Phân tích nguyên nhân gốc của một vấn đề công việc/xã hội dùng ít nhất 3 cấu trúc chẻ hoặc fronting.'},
 write:{prompt:'Write an analytical paragraph (9 sentences) using cleft sentences and fronting.',min:100,model:'What defines a strong team is not individual talent but shared goals. It was last year that our department changed its approach. Central to this change was open communication. What we discovered was that most delays came from unclear responsibilities. Particularly striking was the improvement in morale. The new system reduced errors, thereby saving time, albeit at some initial cost. Whereas the old process relied on email, the new one uses a shared dashboard.'}},

{id:'c1u6',lv:'C1',title:'Văn nghị luận & báo cáo: lập trường, hedging & mạch lạc',goal:'Viết bài luận/báo cáo có luận điểm rõ, thận trọng, mạch lạc và tự nhiên.',
 vocab:[['undoubtedly','/ʌnˈdaʊtɪdli/','chắc chắn','This is undoubtedly a key factor.'],['arguably','/ˈɑːrɡjuːəbli/','có thể cho là','Arguably the best option.'],['notably','/ˈnoʊtəbli/','đáng chú ý','Notably, costs fell.'],['admittedly','/ədˈmɪtɪdli/','phải thừa nhận','Admittedly, it’s expensive.'],['to a large extent','/tuː ə lɑːrdʒ ɪkˈstent/','ở mức độ lớn','To a large extent, I agree.'],['it follows that','/ɪt ˈfɑːloʊz ðæt/','suy ra','It follows that costs will rise.'],['draw a conclusion','/drɔː ə kənˈkluːʒn/','rút ra kết luận','We can draw a conclusion.'],['in the light of','/ɪn ðə ˈlaɪt əv/','xét đến','In the light of these findings…']],
 grammar:{body:'<ul><li><b>Stance adverbs</b> (thể hiện lập trường): <i>arguably, undoubtedly, admittedly, notably, presumably, evidently.</i></li><li><b>Hedging</b>: <i>appears to, tends to, is likely to, may well, to a large extent, it would seem that…</i></li><li><b>Cấu trúc luận điểm</b>: Mở bài (bối cảnh + luận điểm) → Thân bài (1 ý/đoạn: câu chủ đề → giải thích → bằng chứng → liên kết) → Kết bài (tóm + hàm ý).</li><li><b>Liên kết</b>: <i>In the light of…, It follows that…, Nevertheless, Conversely, Consequently, By contrast.</i></li><li><b>Báo cáo (report)</b>: dùng tiêu đề, bullet, giọng khách quan, câu bị động và danh hóa.</li></ul>',
  quiz:[{q:'“___ , the plan is expensive, but it may save money in the long run.”',o:['Admittedly','Nobody','Hardly'],a:0,e:'Admittedly = phải thừa nhận.'},{q:'Which sentence is best hedged?',o:['The policy will fail.','The policy may well fail to achieve its aims.','The policy fails.'],a:1,e:'may well + hedging.'},{q:'“In the ___ of these results, we should reconsider.”',o:['light','sight','view of'],a:0,e:'in the light of.'},{q:'A strong paragraph usually starts with:',o:['A topic sentence','An example only','A question'],a:0,e:'Câu chủ đề.'}]},
 listen:{dialog:[['A','How can I make my essay sound more balanced?','Làm sao để bài luận cân bằng hơn?'],['B','Use hedging: say “arguably” or “it would seem that”.','Dùng hedging: “arguably” hoặc “it would seem that”.'],['A','And what about the conclusion?','Còn phần kết bài?'],['B','Summarise your argument and point to implications. Avoid introducing new ideas.','Tóm tắt lập luận và nêu hàm ý. Tránh ý mới.'],['A','Admittedly, that’s harder than it sounds.','Phải thừa nhận, khó hơn nghe có vẻ.']],
  qs:[{q:'How can the essay sound balanced?',o:['Use hedging','Use short sentences only','Avoid examples'],a:0,e:'“Use hedging”.'},{q:'What should the conclusion avoid?',o:['New ideas','A summary','Implications'],a:0,e:'“Avoid introducing new ideas”.'}]},
 read:{text:'Remote work is arguably the most significant change to employment in decades. Admittedly, it offers clear benefits: reduced commuting, greater flexibility and access to a wider talent pool. Nevertheless, evidence suggests that it may well weaken team cohesion and blur the boundary between work and home. To a large extent, the outcome appears to depend on management practice rather than on technology itself. In the light of these findings, organisations would be wise to adopt hybrid models, thereby retaining the advantages while limiting the drawbacks.',
  qs:[{q:'What is remote work called by the writer?',o:['Arguably the most significant change in employment in decades','A temporary fashion','A failure'],a:0,e:'câu 1.'},{q:'What is a possible drawback?',o:['Weaker team cohesion','Higher taxes','Lower salaries'],a:0,e:'“weaken team cohesion”.'},{q:'What does the writer recommend?',o:['Hybrid models','Full office work','Full remote work'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['Arguably, the most important factor is trust.','In the light of these findings, we should reconsider our approach.'],prompt:'Trình bày lập luận 2 phút: “Will artificial intelligence create more jobs than it destroys?” dùng hedging và stance adverbs.'},
 write:{prompt:'Write a balanced argumentative essay (12 sentences): “Should governments limit working hours by law?”',min:150,model:'The question of whether governments should limit working hours is increasingly debated. Proponents argue that legal limits protect health and improve productivity. Admittedly, overwork is associated with stress and reduced concentration. Nevertheless, critics point out that strict regulation may reduce flexibility and harm small businesses. To a large extent, the answer appears to depend on the nature of the industry. In sectors such as healthcare, it may well be impractical to impose fixed limits. Notably, several countries that have introduced shorter weeks report stable output. In the light of this evidence, a flexible framework, rather than a rigid ceiling, would arguably be most effective. It follows that governments should set minimum standards while allowing sectors to adapt. On balance, moderate regulation seems the most defensible approach.'}}
);

